+-- =============================================================================
+-- 650 — LE PUSH SI PRENDONO IN CARICO, COSÌ DUE GIRI NON LE MANDANO DUE VOLTE (R03-009)
+-- =============================================================================
+--
+-- NON APPLICATA. La applica Nicola.
+--
+-- ── Cosa c'e' che non va, in parole semplici ─────────────────────────────────
+-- Il giro delle notifiche push (app/api/cron/send-push) parte ogni 5 minuti e
+-- puo' durare fino a 300 secondi. Legge le notifiche con `pushed_at` vuoto,
+-- manda le push e solo alla fine segna `pushed_at`. Se due giri si
+-- sovrappongono (un giro lento e quello dopo, o un giro fatto a mano), tutti e
+-- due leggono le stesse righe ancora vuote e la stessa push arriva due volte.
+--
+-- ── Cosa fa ──────────────────────────────────────────────────────────────────
+-- Aggiunge `push_claimed_at`: quando un giro ha preso in carico la notifica.
+-- Il giro la prende con UNA scrittura condizionata, prima di mandare:
+--   UPDATE notifications SET push_claimed_at = now()
+--    WHERE id IN (...) AND pushed_at IS NULL
+--      AND (push_claimed_at IS NULL OR push_claimed_at < now() - '10 minutes')
+--   RETURNING id;
+-- e manda solo le righe che gli tornano indietro: il secondo giro trova la
+-- presa del primo e non le riceve. Una presa vale 10 minuti (piu' dei 300
+-- secondi di un giro): se il giro che l'ha presa muore, dopo quel tempo la
+-- riprende un altro giro. Le prese non mandate (guasto passeggero, preferenza
+-- non letta) il giro le ridà subito, rimettendo la colonna vuota.
+--
+-- Additiva, idempotente: una colonna vuota per difetto, nessun dato toccato.
+-- Senza questa migrazione la rotta manda come prima (lo dice nel registro).
+-- =============================================================================
+
+BEGIN;
+
+ALTER TABLE public.notifications
+  ADD COLUMN IF NOT EXISTS push_claimed_at timestamptz;
+
+COMMENT ON COLUMN public.notifications.push_claimed_at IS
+  'Quando il giro delle push ha preso in carico la notifica (presa valida 10 minuti). NULL = libera. Vedi migrazione 650.';
+
+COMMIT;
+
+NOTIFY pgrst, 'reload schema';
