+-- =============================================================================
+-- R03-009 — Le push si prendono in carico: due giri non mandano la stessa (migrazione 650)
+-- =============================================================================
+--   tests/sql/harness/apply.sh mycity_test && tests/sql/harness/run.sh mycity_test
