+-- La presa è la scrittura condizionata che il giro di app/api/cron/send-push fa prima di mandare:
+-- prende solo le righe con `pushed_at` vuoto e senza una presa viva, e manda solo quelle che gli
+-- tornano indietro.
+-- ① il primo giro prende le due notifiche da mandare, non quella già mandata
+-- ② il secondo giro, subito dopo, non ne prende nessuna
+-- ③ la presa di un giro morto, vecchia di 11 minuti, torna disponibile
+-- ④ una presa ridata (colonna di nuovo vuota) si riprende subito
+-- ⑤ una notifica già mandata non si prende mai, neanche con una presa scaduta
+-- Tutto con ROLLBACK.
+-- =============================================================================
+
+BEGIN;
+
+CREATE TEMP TABLE esiti (nome text, ok boolean, dettaglio text) ON COMMIT DROP;
+
+INSERT INTO auth.users (id, email, raw_user_meta_data) VALUES
+  ('77777777-7777-7777-7777-777777777777', 'campanella@test.it', '{"role":"seller"}');
+
+INSERT INTO public.notifications (id, user_id, title, category, created_at, pushed_at) VALUES
+  ('a0000000-0000-4000-8000-000000000001', '77777777-7777-7777-7777-777777777777', 'Nuovo ordine', 'order', now() - interval '1 minute', NULL),
+  ('a0000000-0000-4000-8000-000000000002', '77777777-7777-7777-7777-777777777777', 'Ordine pronto', 'order', now() - interval '1 minute', NULL),
+  ('a0000000-0000-4000-8000-000000000003', '77777777-7777-7777-7777-777777777777', 'Già mandata', 'order', now() - interval '1 minute', now());
+
+-- La presa, come la scrive la rotta: id della lettura, pushed_at vuoto, nessuna presa viva.
+CREATE TEMP TABLE prese (giro text, ids uuid[]) ON COMMIT DROP;
+CREATE FUNCTION pg_temp.prendi(giro text) RETURNS uuid[] LANGUAGE sql AS $$
+  WITH presa AS (
+    UPDATE public.notifications
+       SET push_claimed_at = now()
+     WHERE id IN ('a0000000-0000-4000-8000-000000000001', 'a0000000-0000-4000-8000-000000000002',
+                  'a0000000-0000-4000-8000-000000000003')
+       AND pushed_at IS NULL
+       AND (push_claimed_at IS NULL OR push_claimed_at < now() - interval '10 minutes')
+    RETURNING id
+  )
+  SELECT coalesce(array_agg(id ORDER BY id), '{}') FROM presa
+$$;
+
+-- ① e ②
+INSERT INTO prese SELECT 'A', pg_temp.prendi('A');
+INSERT INTO prese SELECT 'B', pg_temp.prendi('B');
+INSERT INTO esiti SELECT 'il primo giro prende le due da mandare',
+  ids = ARRAY['a0000000-0000-4000-8000-000000000001', 'a0000000-0000-4000-8000-000000000002']::uuid[], ids::text
+  FROM prese WHERE giro = 'A';
+INSERT INTO esiti SELECT 'il secondo giro non prende niente: niente push doppie', cardinality(ids) = 0, ids::text
+  FROM prese WHERE giro = 'B';
+
+-- ③ Il giro che aveva preso la prima è morto 11 minuti fa.
+UPDATE public.notifications SET push_claimed_at = now() - interval '11 minutes'
+ WHERE id = 'a0000000-0000-4000-8000-000000000001';
+INSERT INTO prese SELECT 'C', pg_temp.prendi('C');
+INSERT INTO esiti SELECT 'la presa di un giro morto torna disponibile dopo la scadenza',
+  ids = ARRAY['a0000000-0000-4000-8000-000000000001']::uuid[], ids::text
+  FROM prese WHERE giro = 'C';
+
+-- ④ Il giro ridà la seconda (invio non riuscito): solo se la presa è ancora la sua.
+UPDATE public.notifications SET push_claimed_at = NULL
+ WHERE id = 'a0000000-0000-4000-8000-000000000002' AND push_claimed_at = now();
+INSERT INTO prese SELECT 'D', pg_temp.prendi('D');
+INSERT INTO esiti SELECT 'una presa ridata si riprende subito',
+  ids = ARRAY['a0000000-0000-4000-8000-000000000002']::uuid[], ids::text
+  FROM prese WHERE giro = 'D';
+
+-- ⑤ La già mandata, anche con una presa vecchia, non torna.
+UPDATE public.notifications SET push_claimed_at = now() - interval '1 hour'
+ WHERE id = 'a0000000-0000-4000-8000-000000000003';
+INSERT INTO prese SELECT 'E', pg_temp.prendi('E');
+INSERT INTO esiti SELECT 'una notifica già mandata non si prende mai', cardinality(ids) = 0, ids::text
+  FROM prese WHERE giro = 'E';
+
+DO $$
+DECLARE r record; rossi int;
+BEGIN
+  FOR r IN SELECT * FROM esiti ORDER BY nome LOOP
+    RAISE INFO '%  %  — %', CASE WHEN r.ok THEN 'ok  ' ELSE 'ROTTO' END, r.nome, r.dettaglio;
+  END LOOP;
+  SELECT count(*) INTO rossi FROM esiti WHERE ok IS NOT TRUE;
+  IF rossi > 0 THEN
+    RAISE EXCEPTION '% controlli su % sono rossi', rossi, (SELECT count(*) FROM esiti);
+  END IF;
+  RAISE INFO 'tutti verdi: % controlli', (SELECT count(*) FROM esiti);
+END $$;
+
+ROLLBACK;
