+/**
+ * R03-009 — LE PUSH NON PARTONO DUE VOLTE SE DUE GIRI SI SOVRAPPONGONO.
+ *
+ * Il giro delle push (ogni 5 minuti, fino a 300 secondi) leggeva le notifiche con `pushed_at`
+ * vuoto, mandava, e segnava `pushed_at` solo alla fine. Un secondo giro partito nel frattempo
+ * leggeva le stesse righe, ancora vuote, e mandava la stessa push un'altra volta. Adesso il giro
+ * prende le righe con una scrittura condizionata (`push_claimed_at`, migrazione 650) e manda solo
+ * quelle che gli tornano; la presa di un giro morto torna disponibile dopo dieci minuti.
+ *
+ * Il finto database tiene le righe in memoria e applica i filtri, compresa la presa: i due giri qui
+ * sono sovrapposti davvero (il primo resta fermo dentro l'invio mentre gira il secondo).
+ */
+import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
+
+type Riga = Record<string, unknown>;
+
+const mondo = vi.hoisted(() => ({
+  righe: [] as Array<Record<string, unknown>>,
+  /** Ogni push consegnata: l'id della notifica. */
+  inviate: [] as string[],
+  /** Se c'è, l'invio aspetta questa promessa (il primo giro resta «in volo»). */
+  cancello: null as null | Promise<void>,
+  /** Si risolve quando un invio è partito. */
+  partito: null as null | (() => void),
+  consegna: { delivered: 1, total: 1 },
+  errorePresa: null as null | { code?: string; message: string },
+}));
+
+vi.mock('@/lib/api/middleware', () => ({
+  withCronAuth: (h: (req: unknown) => unknown) => (req: unknown) => h(req),
+}));
+vi.mock('@/lib/logger', () => ({
+  logger: { error: vi.fn(), warn: vi.fn(), info: vi.fn(), debug: vi.fn(), spesa: vi.fn() },
+}));
+vi.mock('@/lib/push/send', () => ({
+  isPushConfigured: () => true,
+  iscrizioniPerUtenti: async (_s: unknown, ids: string[]) => new Map(ids.map((u) => [u, [{ id: `s-${u}` }]])),
+  sendPushToUser: async (_s: unknown, _u: string, payload: { tag?: string }) => {
+    mondo.partito?.();
+    if (mondo.cancello) await mondo.cancello;
+    if (mondo.consegna.delivered > 0) mondo.inviate.push(String(payload.tag));
+    return { ...mondo.consegna };
+  },
+}));
+
+/** Una query sulla tabella delle notifiche che applica davvero i filtri usati dal giro. */
+function query() {
+  let azione: 'select' | 'update' = 'select';
+  let valori: Riga = {};
+  let tetto = Infinity;
+  const filtri: Array<(r: Riga) => boolean> = [];
+  const q: Record<string, unknown> = {
+    select: () => q,
+    update: (v: Riga) => { azione = 'update'; valori = v; return q; },
+    is: (c: string, v: unknown) => { filtri.push((r) => (r[c] ?? null) === v); return q; },
+    eq: (c: string, v: unknown) => { filtri.push((r) => r[c] === v); return q; },
+    gte: (c: string, v: string) => { filtri.push((r) => String(r[c]) >= v); return q; },
+    in: (c: string, vs: unknown[]) => { filtri.push((r) => vs.includes(r[c])); return q; },
+    or: (espressione: string) => {
+      // La sola forma col «lt» è la presa: «colonna.is.null,colonna.lt.<ora>».
+      const presa = /^(\w+)\.is\.null,\1\.lt\.(.+)$/.exec(espressione);
+      if (presa) filtri.push((r) => r[presa[1]] == null || String(r[presa[1]]) < presa[2]);
+      return q;
+    },
+    order: () => q,
+    limit: (n: number) => { tetto = n; return q; },
+    then: (ok: (v: unknown) => unknown, ko?: (e: unknown) => unknown) => {
+      const esegui = async () => {
+        if (azione === 'update' && 'push_claimed_at' in valori && valori.push_claimed_at !== null && mondo.errorePresa) {
+          return { data: null, error: mondo.errorePresa };
+        }
+        const scelte = mondo.righe.filter((r) => filtri.every((f) => f(r)));
+        if (azione === 'update') {
+          for (const r of scelte) Object.assign(r, valori);
+          return { data: scelte.map((r) => ({ ...r })), error: null };
+        }
+        return { data: scelte.slice(0, tetto).map((r) => ({ ...r })), error: null };
+      };
+      return esegui().then(ok, ko);
+    },
+  };
+  return q;
+}
+
+vi.mock('@/lib/supabase/server', () => ({
+  getAdminSupabase: () => ({
+    from: () => query(),
+    rpc: async () => ({ data: true, error: null }),
+  }),
+}));
+
+import { POST } from '@/app/api/cron/send-push/route';
+
+const ADESSO = new Date('2026-11-21T18:00:00Z').getTime();
+const MINUTO = 60_000;
+
+function notifica(id: string, campi: Riga = {}): Riga {
+  return {
+    id, user_id: `u-${id}`, title: 'Ordine pronto', body: null, link: null, category: 'order',
+    created_at: new Date(ADESSO - 2 * MINUTO).toISOString(), pushed_at: null, push_claimed_at: null,
+    ...campi,
+  };
+}
+
+const unGiro = async () => {
+  const r = await (POST as unknown as (req: Request) => Promise<Response>)(
+    new Request('http://localhost/api/cron/send-push?a_mano=1', { method: 'POST' }),
+  );
+  return { status: r.status, corpo: (await r.json()) as Record<string, unknown> };
+};
+
+const riga = (id: string) => mondo.righe.find((r) => r.id === id)!;
+
+beforeEach(() => {
+  vi.useFakeTimers({ toFake: ['Date'] });
+  vi.setSystemTime(ADESSO);
+  mondo.righe = [];
+  mondo.inviate = [];
+  mondo.cancello = null;
+  mondo.partito = null;
+  mondo.consegna = { delivered: 1, total: 1 };
+  mondo.errorePresa = null;
+});
+afterEach(() => {
+  vi.useRealTimers();
+});
+
+describe('R03-009 · due giri sovrapposti non mandano la stessa push due volte', () => {
+  it('il secondo giro parte mentre il primo è ancora dentro l invio: ogni push parte una volta sola', async () => {
+    mondo.righe = [notifica('n1'), notifica('n2')];
+    let apri: () => void = () => {};
+    mondo.cancello = new Promise<void>((r) => { apri = r; });
+    const primoInVolo = new Promise<void>((r) => { mondo.partito = r; });
+
+    const primo = unGiro();
+    await primoInVolo;
+    // Il primo giro è fermo dentro l'invio: `pushed_at` è ancora vuoto. Parte il secondo.
+    mondo.cancello = null;
+    mondo.partito = null;
+    const secondo = await unGiro();
+    apri();
+    const esito = await primo;
+
+    expect(mondo.inviate.filter((t) => t === 'n1'), 'la stessa push arriva due volte').toHaveLength(1);
+    expect(mondo.inviate.filter((t) => t === 'n2'), 'la stessa push arriva due volte').toHaveLength(1);
+    expect(secondo.corpo.sent, 'il secondo giro non doveva mandare niente').toBe(0);
+    expect(esito.corpo.sent).toBe(2);
+    expect(riga('n1').pushed_at).not.toBeNull();
+  });
+
+  it('una presa viva di un altro giro (2 minuti fa) non si tocca; una di un giro morto (11 minuti fa) si riprende', async () => {
+    mondo.righe = [
+      notifica('viva', { push_claimed_at: new Date(ADESSO - 2 * MINUTO).toISOString() }),
+      notifica('morta', { push_claimed_at: new Date(ADESSO - 11 * MINUTO).toISOString() }),
+    ];
+    await unGiro();
+    expect(mondo.inviate, 'la presa di un giro vivo è stata scavalcata').not.toContain('viva');
+    expect(mondo.inviate, 'la presa di un giro morto non torna mai disponibile').toContain('morta');
+    expect(riga('viva').pushed_at).toBeNull();
+  });
+
+  it('una push non consegnata si ridà subito: il giro dopo la riprende', async () => {
+    mondo.righe = [notifica('n1')];
+    mondo.consegna = { delivered: 0, total: 1 };
+    await unGiro();
+    expect(riga('n1').pushed_at).toBeNull();
+    expect(riga('n1').push_claimed_at, 'la presa resta e il giro dopo non la vede per dieci minuti').toBeNull();
+    mondo.consegna = { delivered: 1, total: 1 };
+    vi.setSystemTime(ADESSO + 5 * MINUTO);
+    await unGiro();
+    expect(mondo.inviate).toEqual(['n1']);
+  });
+
+  it('se la presa non si scrive per un guasto, non si manda niente e il giro risponde 503', async () => {
+    mondo.righe = [notifica('n1')];
+    mondo.errorePresa = { message: 'canceling statement due to statement timeout' };
+    const { status } = await unGiro();
+    expect(status).toBe(503);
+    expect(mondo.inviate, 'senza presa due giri possono mandare la stessa push').toEqual([]);
+  });
+
+  it('prima della migrazione 650 (colonna che non c è) si manda come prima', async () => {
+    mondo.righe = [notifica('n1')];
+    mondo.errorePresa = { code: 'PGRST204', message: "Could not find the 'push_claimed_at' column of 'notifications' in the schema cache" };
+    const { status, corpo } = await unGiro();
+    expect(status).toBe(200);
+    expect(corpo.sent).toBe(1);
+    expect(riga('n1').pushed_at).not.toBeNull();
+  });
+});
